import React from 'react';
import './style.css';
import profileImg from './profile.jpg';

export default function ProfileCard() {
  return (
    <article className="profile-card">
      <img className="profile-photo" src={profileImg} alt="Profile" />
      <h1>Alex Morgan</h1>
      <p className="role">Full Stack Developer</p>
      <p className="bio">Building clean, accessible web experiences with React and TypeScript.</p>
      <div className="actions">
        <button>View Profile</button>
        <button className="secondary">Contact Me</button>
      </div>
    </article>
  );
}
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px; font-family: Inter, system-ui, sans-serif; background: #f4f7fb; color: #172033; }
.profile-card { width: min(380px, 100%); background: white; padding: 32px; border-radius: 24px; text-align: center; box-shadow: 0 18px 50px rgba(23,32,51,.12); }
.profile-photo { width: 132px; height: 132px; object-fit: cover; border-radius: 50%; border: 6px solid white; box-shadow: 0 8px 24px rgba(23,32,51,.18); }
h1 { margin: 20px 0 4px; font-size: 28px; }
.role { margin: 0; padding-left:100px; color: #667085; font-size: 18px; }
.bio { color: #475467; line-height: 1.6; }
.actions { display: flex; gap: 12px; margin-top: 24px; }
button { flex: 1; border: 0; border-radius: 12px; padding: 12px 16px; background: #2563eb; color: white; font-weight: 700; cursor: pointer; }
button.secondary { background: #eef2ff; color: #1d4ed8; }
button:hover { filter: brightness(.96); }
