        <button className="secondary">Contact Me</button>
      </div>
    </article>
  );
}
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px; font-family: Inter, system-ui, sans-serif; background: #f4f7fb; color: #172033; }
.profile-card { width: min(380px, 100%); min-width: 0; background: white; padding: 32px; border-radius: 24px; text-align: center; overflow-wrap: anywhere; box-shadow: 0 18px 50px rgba(23,32,51,.12); }
.profile-photo { width: 132px; max-width: 100%; height: auto; aspect-ratio: 1; object-fit: cover; border-radius: 50%; border: 6px solid white; box-shadow: 0 8px 24px rgba(23,32,51,.18); }
.profile-heading { margin-top: 20px; }
.profile-card h1 { margin: 20px 0 4px; font-size: 28px; line-height: 1.2; }
.profile-heading h1 { margin-top: 0; }
.role { margin: 0; color: #667085; font-size: 18px; line-height: 1.5; }
.bio { margin: 16px 0 0; color: #475467; line-height: 1.6; }
.actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
.actions button { flex: 1 1 130px; min-width: 0; max-width: 100%; white-space: normal; overflow-wrap: anywhere; border: 0; border-radius: 12px; padding: 12px 16px; background: #2563eb; color: white; font-weight: 700; line-height: 1.4; cursor: pointer; }
button.secondary { background: #eef2ff; color: #1d4ed8; }
button:hover { filter: brightness(.96); }

@media (max-width: 400px) {
  body { padding: 16px; }
  .profile-card { padding: 24px; }
}

